import { createReadStream, existsSync, statSync } from 'node:fs'
import { join, extname, normalize, sep } from 'node:path'
import { createServer } from 'node:http'
import { handleSewpApi } from './server/sewp-api.mjs'
import { handleDataApi } from './server/data-api.mjs'
import { handleManagedFundsApi } from './server/managed-funds-api.mjs'
import { getSewpSupabase } from './server/sewp-supabase.mjs'
import { getSupabasePasswordAuthClient } from './server/sewp-supabase.mjs'
import { handleAtlasAuthApi } from './server/atlas-auth-api.mjs'
import { handleCatalogApi } from './server/catalog-api.mjs'
import { handleTdSynnexApi } from './server/td-synnex-api.mjs'
import { handlePricingVerificationApi } from './server/pricing-verification-api.mjs'

const port = Number(process.env.PORT || 4173)
const root = join(process.cwd(), 'dist')
const rootPrefix = root.endsWith(sep) ? root : `${root}${sep}`
const atlasPurchaseOrders = new Map()
const cimsOutboundEvents = new Map()
const barcodeScanEvents = []
const labelPrintJobs = []
const integrationSyncLogs = []

const contentTypes = {
  '.css': 'text/css; charset=utf-8',
  '.html': 'text/html; charset=utf-8',
  '.ico': 'image/x-icon',
  '.jpg': 'image/jpeg',
  '.js': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.png': 'image/png',
  '.svg': 'image/svg+xml',
  '.webp': 'image/webp',
}

function resolvePath(url = '/') {
  const pathname = decodeURIComponent(new URL(url, 'http://localhost').pathname)
  const requested = normalize(join(root, pathname))
  if (requested !== root && !requested.startsWith(rootPrefix)) return join(root, 'index.html')

  if (existsSync(requested) && statSync(requested).isFile()) return requested

  return join(root, 'index.html')
}

function sendJson(response, statusCode, payload) {
  response.statusCode = statusCode
  response.setHeader('Content-Type', 'application/json; charset=utf-8')
  response.setHeader('X-Content-Type-Options', 'nosniff')
  response.end(JSON.stringify(payload))
}

function readJsonBody(request, maximumBytes = 1_000_000) {
  return new Promise((resolve, reject) => {
    let raw = ''
    request.setEncoding('utf8')
    request.on('data', chunk => {
      raw += chunk
      if (Buffer.byteLength(raw) > maximumBytes) {
        reject(new Error('Request body too large'))
        request.destroy()
      }
    })
    request.on('end', () => {
      if (!raw.trim()) {
        resolve({})
        return
      }
      try {
        resolve(JSON.parse(raw))
      } catch (error) {
        reject(error)
      }
    })
    request.on('error', reject)
  })
}

function readBufferBody(request, maximumBytes = 25 * 1024 * 1024) {
  return new Promise((resolve, reject) => {
    const chunks = []
    let size = 0
    request.on('data', chunk => {
      size += chunk.length
      if (size > maximumBytes) {
        reject(new Error('Request body too large'))
        request.destroy()
        return
      }
      chunks.push(chunk)
    })
    request.on('end', () => resolve(Buffer.concat(chunks)))
    request.on('error', reject)
  })
}

function appendSyncLog({ direction, entity, externalId, status = 'Pending', message }) {
  const log = {
    id: `sync-${Date.now()}-${integrationSyncLogs.length + 1}`,
    direction,
    entity,
    externalId,
    status,
    attempts: 1,
    lastAttemptAt: new Date().toISOString(),
    message,
  }
  integrationSyncLogs.unshift(log)
  return log
}

async function handleCimsApi(request, response, pathname) {
  if (request.method === 'GET' && pathname === '/api/cims/health') {
    sendJson(response, 200, {
      service: 'Cronos Inventory Management System',
      status: 'ok',
      atlasIntegration: 'webhook-ready',
      warehouses: ['Lexington Park, MD', 'Evans, GA', 'Virginia Beach, VA'],
    })
    return true
  }

  if (request.method === 'GET' && pathname === '/api/cims/integration/logs') {
    sendJson(response, 200, { logs: integrationSyncLogs })
    return true
  }

  if (request.method === 'POST' && pathname === '/api/cims/barcodes/scan') {
    try {
      const payload = await readJsonBody(request)
      if (!payload.scannedValue) {
        sendJson(response, 400, { error: 'scannedValue is required' })
        return true
      }
      const event = {
        id: `scan-${Date.now()}-${barcodeScanEvents.length + 1}`,
        scannedValue: payload.scannedValue,
        scanSource: payload.scanSource || 'Manual',
        matchType: payload.matchType || null,
        matchedExternalId: payload.matchedExternalId || null,
        warehouseCode: payload.warehouseCode || null,
        result: payload.result || 'No Match',
        occurredAt: new Date().toISOString(),
      }
      barcodeScanEvents.unshift(event)
      sendJson(response, 201, { status: 'logged', event })
    } catch (error) {
      sendJson(response, 400, { error: 'Invalid JSON payload' })
    }
    return true
  }

  if (request.method === 'POST' && pathname === '/api/cims/labels/print') {
    try {
      const payload = await readJsonBody(request)
      if (!payload.labelType || !payload.barcodeValue || !payload.labelSize) {
        sendJson(response, 400, { error: 'labelType, barcodeValue, and labelSize are required' })
        return true
      }
      const job = {
        id: `label-${Date.now()}-${labelPrintJobs.length + 1}`,
        labelType: payload.labelType,
        labelSize: payload.labelSize,
        barcodeValue: payload.barcodeValue,
        entityType: payload.entityType || 'unknown',
        entityExternalId: payload.entityExternalId || null,
        reprint: Boolean(payload.reprint),
        printedAt: new Date().toISOString(),
      }
      labelPrintJobs.unshift(job)
      appendSyncLog({
        direction: 'CIMS to Atlas',
        entity: 'label_print',
        externalId: job.barcodeValue,
        status: 'Synced',
        message: `${job.labelType} ${job.reprint ? 'reprinted' : 'printed'} for audit history.`,
      })
      sendJson(response, 201, { status: 'printed', job })
    } catch (error) {
      sendJson(response, 400, { error: 'Invalid JSON payload' })
    }
    return true
  }

  if (request.method === 'POST' && pathname === '/api/cims/webhooks/atlas/purchase-order') {
    try {
      const payload = await readJsonBody(request)
      if (!payload.externalId && !payload.poNumber) {
        sendJson(response, 400, { error: 'externalId or poNumber is required' })
        return true
      }

      const externalId = payload.externalId || payload.poNumber
      const existing = atlasPurchaseOrders.get(externalId)
      atlasPurchaseOrders.set(externalId, {
        ...existing,
        ...payload,
        externalId,
        receivedFromAtlasAt: new Date().toISOString(),
      })

      const log = appendSyncLog({
        direction: 'Atlas to CIMS',
        entity: 'purchase_order',
        externalId,
        status: 'Synced',
        message: existing ? 'Atlas PO update merged by external ID.' : 'Atlas PO created in CIMS receiving queue.',
      })

      sendJson(response, existing ? 200 : 201, {
        status: existing ? 'updated' : 'created',
        externalId,
        syncLogId: log.id,
      })
    } catch (error) {
      sendJson(response, 400, { error: 'Invalid JSON payload' })
    }
    return true
  }

  if (request.method === 'POST' && pathname === '/api/cims/webhooks/atlas/status') {
    try {
      const payload = await readJsonBody(request)
      if (!payload.eventType || !payload.externalId) {
        sendJson(response, 400, { error: 'eventType and externalId are required' })
        return true
      }

      cimsOutboundEvents.set(payload.externalId, {
        ...payload,
        queuedForAtlasAt: new Date().toISOString(),
      })
      const log = appendSyncLog({
        direction: 'CIMS to Atlas',
        entity: payload.eventType,
        externalId: payload.externalId,
        status: 'Pending',
        message: 'Outbound warehouse event queued for Atlas acknowledgement.',
      })

      sendJson(response, 202, { status: 'queued', syncLogId: log.id })
    } catch (error) {
      sendJson(response, 400, { error: 'Invalid JSON payload' })
    }
    return true
  }

  if (request.method === 'POST' && pathname === '/api/cims/sync/retry') {
    try {
      const payload = await readJsonBody(request)
      const retryable = integrationSyncLogs.filter(log => !payload.externalId || log.externalId === payload.externalId)
      retryable.forEach(log => {
        if (log.status !== 'Synced') {
          log.status = 'Pending'
          log.attempts += 1
          log.lastAttemptAt = new Date().toISOString()
          log.message = 'Manual retry requested from CIMS admin.'
        }
      })
      sendJson(response, 202, { status: 'retry-queued', count: retryable.length })
    } catch (error) {
      sendJson(response, 400, { error: 'Invalid JSON payload' })
    }
    return true
  }

  return false
}

createServer(async (request, response) => {
  const pathname = decodeURIComponent(new URL(request.url || '/', 'http://localhost').pathname)
  if (await handleAtlasAuthApi({ request, response, pathname, sendJson, readJsonBody, supabase: getSewpSupabase(), passwordAuthClient: getSupabasePasswordAuthClient() })) return
  if (await handleTdSynnexApi({ request, response, pathname, sendJson, readJsonBody, authClient: getSupabasePasswordAuthClient() })) return
  if (await handlePricingVerificationApi({ request, response, pathname, sendJson, readJsonBody, authClient: getSupabasePasswordAuthClient(), supabase: getSewpSupabase() })) return
  if (await handleCatalogApi({ request, response, pathname, sendJson, readJsonBody, readBufferBody, supabase: getSewpSupabase() })) return
  if (await handleDataApi({ request, response, pathname, sendJson, readJsonBody, supabase: getSewpSupabase() })) return
  if (await handleManagedFundsApi({ request, response, pathname, sendJson, readJsonBody, readBufferBody, supabase: getSewpSupabase() })) return
  if (await handleSewpApi({ request, response, pathname, sendJson, readJsonBody, readBufferBody })) return
  if (pathname.startsWith('/api/cims/') && await handleCimsApi(request, response, pathname)) return

  const filePath = resolvePath(request.url)
  const contentType = contentTypes[extname(filePath)] || 'application/octet-stream'

  response.setHeader('Content-Type', contentType)
  response.setHeader('X-Content-Type-Options', 'nosniff')
  response.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin')

  createReadStream(filePath)
    .on('error', () => {
      response.statusCode = 404
      response.end('Not found')
    })
    .pipe(response)
}).listen(port, '0.0.0.0', () => {
  console.log(`Cronos Procurement app listening on port ${port}`)
})

import { randomUUID } from 'node:crypto'
import { authenticateSewpRequest } from './sewp-auth.mjs'
import { applyManagedFundsCommand, initializeManagedFunds, reconcileManagedProject, canManageFunds, isManagedFunds } from '../src/domain/managedFunds.mjs'

const migrationActor = { id: 'atlas-managed-funds-migration', name: 'Atlas legacy migration', role: 'admin' }
export class ManagedFundsRepository {
  constructor(supabase) { this.db = supabase }
  async project(id) {
    const { data, error } = await this.db.from('app_records').select('data').eq('record_type', 'projects').eq('record_key', 'all').maybeSingle()
    if (error) throw error
    return (Array.isArray(data?.data) ? data.data : []).find(p => p.id === id)
  }
  async state(id) {
    const { data, error } = await this.db.from('atlas_managed_funds').select('state,revision').eq('project_id', id).maybeSingle()
    if (error) { const e = new Error('Managed Funds persistence is unavailable. Apply the Managed Funds database migration.'); e.status = 503; throw e }
    return data ? { ...data.state, revision: data.revision } : null
  }
  async commit(id, previousProject, project, state, expectedRevision) {
    const clean = value => { if (!value) return null; const { managedFunds, ...rest } = value; return rest }
    const { data, error } = await this.db.rpc('atlas_commit_managed_funds', { p_project_id: id, p_expected_revision: expectedRevision, p_previous_project: clean(previousProject), p_project: clean(project), p_state: state })
    if (error) { const e = new Error(/conflict/i.test(error.message) ? 'This project changed in another session. Reload before retrying.' : error.message); e.status = /conflict/i.test(error.message) ? 409 : 400; throw e }
    return data
  }
  async load(id) {
    const project = await this.project(id)
    if (!project || !isManagedFunds(project)) { const e = new Error('Managed Funds project not found.'); e.status = 404; throw e }
    let state = await this.state(id)
    if (!state) {
      const initialized = initializeManagedFunds(project, migrationActor)
      try { await this.commit(id, project, initialized.project, initialized.state, -1) }
      catch (e) { if (e.status !== 409) throw e }
      state = await this.state(id)
      if (!state) throw new Error('Managed Funds initialization failed.')
      return { project: await this.project(id), state }
    }
    return { project, state }
  }
}

export async function handleManagedFundsApi({ request, response, pathname, sendJson, readJsonBody, readBufferBody, supabase, repository }) {
  if (!pathname.startsWith('/api/managed-funds')) return false
  const auth = await authenticateSewpRequest(request, supabase)
  if (!auth.ok) { sendJson(response, auth.status, { error: auth.error }); return true }
  // Privileged financial roles come exclusively from server-managed metadata.
  // authenticateSewpRequest also supports legacy user_metadata roles for other modules.
  const token = request.headers.authorization.replace(/^Bearer\s+/i, '')
  const verified = await supabase.auth.getUser(token)
  const trusted = verified.data?.user?.app_metadata || {}
  const actor = { ...auth.user, role: trusted.atlas_role || 'engineering', permissions: Array.isArray(trusted.atlas_permissions) ? trusted.atlas_permissions : [] }
  if (!canManageFunds(actor, 'view')) { sendJson(response, 403, { error: 'Managed Funds access is not permitted.' }); return true }
  const repo = repository || new ManagedFundsRepository(supabase)
  try {
    const match = pathname.match(/^\/api\/managed-funds\/([^/]+)(?:\/(commands|project|documents|document-link))?$/)
    if (!match) { sendJson(response, 404, { error: 'Managed Funds route not found.' }); return true }
    const projectId = decodeURIComponent(match[1]), operation = match[2]
    if (operation === 'project' && request.method === 'PUT') {
      const body = await readJsonBody(request, 25 * 1024 * 1024)
      if (!body.project || body.project.id !== projectId || !isManagedFunds(body.project)) throw new Error('Invalid Managed Funds project.')
      const previous = await repo.project(projectId)
      const currentState = await repo.state(projectId)
      if (!previous || !isManagedFunds(previous)) {
        if (!canManageFunds(actor, 'funding')) { sendJson(response, 403, { error: 'Permission required: atlas.managed_funds.funding' }); return true }
        const initial = initializeManagedFunds(body.project, actor)
        await repo.commit(projectId, previous, initial.project, initial.state, -1)
      } else {
        const loaded = currentState ? { project: previous, state: currentState } : await repo.load(projectId)
        if (body.revision !== loaded.state.revision) { sendJson(response, 409, { error: 'This project changed. Reload before saving.' }); return true }
        const reconciled = reconcileManagedProject(loaded.state, loaded.project, body.project, actor)
        await repo.commit(projectId, loaded.project, reconciled.project, reconciled.state, loaded.state.revision)
      }
      sendJson(response, 200, { ...(await repo.load(projectId)), actor }); return true
    }
    const loaded = await repo.load(projectId)
    if (!operation && request.method === 'GET') { sendJson(response, 200, { ...loaded, actor }); return true }
    if (operation === 'commands' && request.method === 'POST') {
      const body = await readJsonBody(request)
      const existing = loaded.state.commands.find(c => c.id === body.command?.id)
      // Check idempotency before revision so a lost success response can be retried safely.
      if (!existing && body.revision !== loaded.state.revision) { sendJson(response, 409, { error: 'This project changed. Reload before retrying.' }); return true }
      if (body.command?.type === 'document') throw new Error('Use the upload endpoint for supporting documents.')
      if (body.command?.type === 'draft_invoice') body.command.input.projectNumber = loaded.project.projectNumber
      const next = applyManagedFundsCommand(loaded.state, body.command, actor, { project: loaded.project })
      if (!existing) await repo.commit(projectId, loaded.project, loaded.project, next, loaded.state.revision)
      sendJson(response, 200, { ...(await repo.load(projectId)), actor }); return true
    }
    if (operation === 'documents' && request.method === 'POST') {
      if (!canManageFunds(actor, 'edit')) { sendJson(response, 403, { error: 'Document upload permission required.' }); return true }
      const query = new URL(request.url, 'http://localhost').searchParams
      const actionId = query.get('actionId'), name = query.get('name') || 'Supporting document', kind = query.get('kind') || 'Supporting document'
      if (!loaded.state.actions.some(a => a.id === actionId)) throw new Error('Action not found.')
      if (Number(query.get('revision')) !== loaded.state.revision) { sendJson(response, 409, { error: 'This project changed. Reload before uploading.' }); return true }
      const ext = name.split('.').pop().toLowerCase()
      if (!['pdf', 'png', 'jpg', 'jpeg', 'txt', 'csv', 'xlsx', 'docx', 'msg', 'eml'].includes(ext)) throw new Error('Unsupported document format.')
      const buffer = await readBufferBody(request, 20 * 1024 * 1024)
      if (!buffer.length) throw new Error('Document is empty.')
      const storagePath = `${projectId}/${actionId}/${randomUUID()}.${ext}`
      const bucket = supabase.storage.from('atlas-managed-funds')
      const upload = await bucket.upload(storagePath, buffer, { contentType: request.headers['content-type'] || 'application/octet-stream', upsert: false })
      if (upload.error) throw upload.error
      try {
        const next = applyManagedFundsCommand(loaded.state, { id: randomUUID(), type: 'document', actionId, input: { name, kind, storagePath, size: buffer.length } }, actor)
        await repo.commit(projectId, loaded.project, loaded.project, next, loaded.state.revision)
      } catch (e) { await bucket.remove([storagePath]); throw e }
      sendJson(response, 201, { ...(await repo.load(projectId)), actor }); return true
    }
    if (operation === 'document-link' && request.method === 'POST') {
      const body = await readJsonBody(request), document = loaded.state.documents.find(d => d.id === body.documentId)
      if (!document) throw new Error('Document not found.')
      const { data, error } = await supabase.storage.from('atlas-managed-funds').createSignedUrl(document.storagePath, 120, { download: document.name })
      if (error) throw error
      sendJson(response, 200, { url: data.signedUrl }); return true
    }
    sendJson(response, 405, { error: 'Method not allowed.' })
  } catch (error) {
    sendJson(response, error.status || 400, { error: error.message || 'Managed Funds operation failed.', ...(error.details ? { funding: error.details } : {}) })
  }
  return true
}

// Shared by the API and UI. All persisted amounts are integer USD cents.
export const ACTION_TYPES = ['Purchase Material', 'Direct Expense / Pass-Through', 'Create Customer Invoice', 'Credit / Adjustment', 'Funding Modification']
export const ACTION_STATUSES = ['Draft', 'Pending Approval', 'Approved', 'In Progress', 'Complete', 'Cancelled']
export const BILLING_STATUSES = ['Not Ready to Bill', 'Ready to Bill', 'Draft Invoice', 'Invoiced', 'Paid', 'Credited']
const ordinary = ['view', 'create', 'edit', 'issue_po', 'expense', 'invoice', 'cancel']
export const MF_PERMISSIONS = { admin: ['*'], procurement: ordinary, sales: ['view', 'create', 'edit', 'invoice'], engineering: ['view'] }
export function canManageFunds(actor, permission) {
  const role = String(actor?.role || '').toLowerCase().replace('procurement team', 'procurement')
  const extra = actor?.permissions instanceof Set ? [...actor.permissions] : actor?.permissions || []
  return (MF_PERMISSIONS[role] || []).includes('*') || (MF_PERMISSIONS[role] || []).includes(permission) || extra.includes(`atlas.managed_funds.${permission}`) || extra.includes('*')
}
function requirePermission(actor, permission) {
  if (!actor?.id || !canManageFunds(actor, permission)) fail(`Permission required: atlas.managed_funds.${permission}`, 403)
}
function fail(message, status = 400, details) { const error = new Error(message); error.status = status; error.details = details; throw error }
export function cents(value) {
  if (value === '' || value === null || value === undefined || !Number.isFinite(Number(value))) fail('Enter a valid monetary amount.')
  const result = Math.round(Number(value) * 100)
  if (!Number.isSafeInteger(result) || Math.abs(result) > 100_000_000_000_000) fail('Monetary amount is out of range.')
  return result
}
function amount(value, signed = false) {
  if (!Number.isSafeInteger(value) || Math.abs(value) > 100_000_000_000_000 || (!signed && value < 0)) fail('Amount must be valid integer cents.')
  return value
}
function required(value, label) { const text = String(value ?? '').trim(); if (!text || text.length > 10000) fail(`${label} is required (maximum 10,000 characters).`); return text }
function date(value) { if (!/^\d{4}-\d{2}-\d{2}$/.test(value || '') || Number.isNaN(Date.parse(value)) || new Date(value).toISOString().slice(0, 10) !== value) fail('A valid date is required.'); return value }
const clone = value => JSON.parse(JSON.stringify(value))
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b)
export function isManagedFunds(project) { return ['Managed Funds', 'Checkbook'].includes(project?.projectType) }
export function financialSummary(state, actionId) {
  const out = { authorized: 0, committed: 0, actualCost: 0, billAmount: 0, invoiced: 0, paid: 0, available: 0, unbilled: 0 }
  for (const tx of state?.transactions || []) {
    if (actionId && tx.actionId !== actionId && tx.adjustmentActionId !== actionId) continue
    for (const field of ['authorized', 'committed', 'actualCost', 'billAmount', 'invoiced', 'paid']) out[field] += tx[field] || 0
  }
  for (const field of ['authorized', 'committed', 'actualCost', 'billAmount', 'invoiced', 'paid']) amount(out[field], true)
  out.available = out.authorized - out.committed
  out.unbilled = out.authorized - out.invoiced
  return out
}
export function actionFinancials(state, actionId) {
  const totals = financialSummary(state, actionId)
  const reserved = state.invoices.filter(i => i.status === 'Draft').flatMap(i => i.allocations).filter(a => a.actionId === actionId).reduce((n, a) => n + a.amount, 0)
  return { ...totals, draftReserved: reserved, billable: Math.min(totals.billAmount,totals.committed) - totals.invoiced - reserved, variance: totals.committed - totals.invoiced }
}
export function billingStatus(state, action) {
  const t = actionFinancials(state, action.id)
  if (state.transactions.some(t => t.actionId === action.id && t.kind === 'Customer Credit') && t.invoiced <= 0) return 'Credited'
  if (t.invoiced > 0 && t.paid >= t.invoiced && t.billable <= 0) return 'Paid'
  if (t.draftReserved > 0) return 'Draft Invoice'
  if (t.invoiced > 0 && t.billable <= 0) return 'Invoiced'
  return action.readyToBill ? 'Ready to Bill' : 'Not Ready to Bill'
}
export function procurementStatus(project, action) {
  const pos = (project.purchaseOrders || []).filter(po => po.actionId === action.id || action.poIds.includes(po.id))
  if (!pos.length) return 'Processing'
  const lines = pos.flatMap(po => (po.lines || []).map(l => ({ ...l, poId: po.id })))
  const shipments = (project.materialShipments || []).filter(s => pos.some(po => po.id === s.poId))
  if (lines.length && lines.every(l => l.status === 'Delivered' || shipments.filter(s => s.poId === l.poId).flatMap(s => s.lines).filter(s => s.melLineItemId === l.id).reduce((n, s) => n + (s.quantityDelivered || 0), 0) >= l.quantityOrdered)) return 'Delivered'
  if (lines.length && lines.every(l => l.quantityReceived >= l.quantityOrdered)) return 'Received'
  if (shipments.length || lines.some(l => /Transit|Shipped/.test(l.status))) return 'In Transit'
  return pos.every(po=>po.status==='PO Generated') ? 'Processing' : 'PO Issued'
}
function newAction(state, input, ctx) {
  if (!ACTION_TYPES.includes(input.type)) fail('Choose a valid Action Type.')
  const action = {
    id: ctx.id(), number: `MF-${String(state.nextAction++).padStart(3, '0')}`, projectId: state.projectId,
    type: input.type, description: required(input.description, 'Description'), requestDate: date(input.requestDate || ctx.now.slice(0, 10)),
    requestor: String(input.requestor || ''), ownerId: String(input.ownerId || ctx.actor.id), ownerName: String(input.ownerName || ctx.actor.name || ''),
    status: 'Draft', authorizedAmount: amount(input.authorizedAmount ?? 0), estimatedCost: amount(input.estimatedCost ?? 0), readyToBill: false,
    vendors: [...new Set((input.vendors || []).map(String))], quoteIds: [], poIds: [], notes: String(input.notes || ''), createdAt: ctx.now,
  }
  state.actions.push(action)
  return action
}
function post(state, ctx, input) {
