import { getSupabaseAccessToken } from './supabaseAuth'
import type { Project } from '../types'
import type { FundsActor, FundsCommand, FundsState } from '../domain/managedFunds.mjs'
export type FundsWorkspace = { project: Project; state: FundsState; actor: FundsActor }
export type FundsError = Error & { status?: number; funding?: Record<string, number> }
const cacheKey = (id: string) => `cronos.managed-funds.${id}`
export function cachedFunds(id: string): FundsState | undefined {
  try { return JSON.parse(window.localStorage.getItem(cacheKey(id)) || 'null') || undefined } catch { return undefined }
}
export function cacheFunds(workspace: FundsWorkspace) {
  const project = { ...workspace.project, managedFundsRevision: workspace.state.revision }
  try {
    window.localStorage.setItem(cacheKey(project.id), JSON.stringify(workspace.state))
    const projects: Project[] = JSON.parse(window.localStorage.getItem('cronos.projects') || '[]')
    window.localStorage.setItem('cronos.projects', JSON.stringify(projects.some(p => p.id === project.id) ? projects.map(p => p.id === project.id ? project : p) : [project, ...projects]))
    window.dispatchEvent(new Event('cronos:projects-changed'))
  } catch { /* The authoritative server response remains available if browser storage is full. */ }
  return { ...workspace, project: { ...project, managedFunds: workspace.state } }
}
async function request<T>(path: string, options: RequestInit = {}): Promise<T> {
  const token = await getSupabaseAccessToken()
  if (!token) throw new Error('Sign in to Atlas to use Managed Funds.')
  const response = await fetch(`/api/managed-funds/${path}`, { ...options, headers: { Authorization: `Bearer ${token}`, ...options.headers } })
  const body = await response.json().catch(() => ({ error: 'Managed Funds service is unavailable.' }))
  if (!response.ok) { const error: FundsError = new Error(body.error || 'Managed Funds request failed.'); error.status = response.status; error.funding = body.funding; throw error }
  return body
}
export async function loadFundsWorkspace(projectId: string) { return cacheFunds(await request<FundsWorkspace>(encodeURIComponent(projectId))) }
export async function saveFundsProject(project: Project) {
  const { managedFunds, ...record } = project
  return cacheFunds(await request<FundsWorkspace>(`${encodeURIComponent(project.id)}/project`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ project: record, revision: project.managedFundsRevision ?? managedFunds?.revision ?? -1 }) }))
}
export async function runFundsCommand(projectId: string, revision: number, command: FundsCommand) {
  return cacheFunds(await request<FundsWorkspace>(`${encodeURIComponent(projectId)}/commands`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ revision, command }) }))
}
export async function uploadFundsDocument(projectId: string, actionId: string, revision: number, file: File, kind: string) {
  if (file.size > 20 * 1024 * 1024) throw new Error('Supporting documents must be 20 MB or smaller.')
  const query = new URLSearchParams({ actionId, name: file.name, kind, revision: String(revision) })
  return cacheFunds(await request<FundsWorkspace>(`${encodeURIComponent(projectId)}/documents?${query}`, { method: 'POST', headers: { 'Content-Type': file.type || 'application/octet-stream' }, body: file }))
}
export async function downloadFundsDocument(projectId: string, documentId: string) {
  const result = await request<{ url: string }>(`${encodeURIComponent(projectId)}/document-link`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ documentId }) })
  const a = document.createElement('a'); a.href = result.url; a.rel = 'noopener'; a.click()
}

import { getAppBaseUrl } from './environment'
import { getSupabaseAuthClient } from './supabaseAuth'
import { authStorage } from './authStorage.mjs'
import { isManagedFunds } from '../domain/managedFunds.mjs'
import { saveFundsProject } from './managedFundsApi'
import type { Project } from '../types'
import { mergeConfirmedChanges, readCollectionSnapshot, saveConfirmedCollection } from './confirmedCollection.mjs'

const volatileCollections = new Map<string, unknown[]>()
const collectionWrites = new Map<string, Promise<unknown>>()
const collectionVersions = new Map<string, number>()

function getClient() {
  return getSupabaseAuthClient()
}

function collectionRaw(storageKey: string) {
  return storageKey === 'cronos.users' ? authStorage.getItem(storageKey) : window.localStorage.getItem(storageKey)
}

export function hasRemoteRecords() {
  return Boolean(getClient())
}

export function getRemoteConfigStatus() {
  return {
    hasUrl: Boolean(import.meta.env.VITE_SUPABASE_URL),
    hasKey: Boolean(import.meta.env.VITE_SUPABASE_ANON_KEY),
    ready: Boolean(getClient()),
  }
}

export async function loadRemoteRecord<T>(recordType: string, recordKey: string, strict = false): Promise<T | null> {
  const supabase = getClient()
  if (!supabase) return null

  const { data, error } = await supabase
    .from('app_records')
    .select('data')
    .eq('record_type', recordType)
    .eq('record_key', recordKey)
    .maybeSingle()

  if (error) {
    if (strict) throw new Error(error.message)
    console.warn(`Unable to load ${recordType}:${recordKey} from Supabase`, error)
    return null
  }

  return (data?.data as T | undefined) ?? null
}

export async function saveRemoteRecord<T>(recordType: string, recordKey: string, data: T): Promise<T> {
  const supabase = getClient()
  if (!supabase) {
    throw new Error('Supabase is not configured. Check VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY in Railway variables.')
  }

  if (recordType === 'projects' && recordKey === 'all' && Array.isArray(data)) {
    const expected = (await readCollectionSnapshot(supabase, recordType, recordKey))?.data ?? []
    return await saveRemoteCollection(recordType, recordKey, data, { expectedItems: expected }) as T
  }
  const { error } = await supabase.from('app_records').upsert(
    {
      record_type: recordType,
      record_key: recordKey,
      data,
    },
    { onConflict: 'record_type,record_key' },
  )

  if (error) {
    console.warn(`Unable to save ${recordType}:${recordKey} to Supabase`, error)
    throw new Error(error.message)
  }
  return data
}

export async function testRemoteConnection() {
  const status = getRemoteConfigStatus()
  if (!status.ready) {
    return {
      ok: false,
      message: `Supabase config missing. URL: ${status.hasUrl ? 'found' : 'missing'}, key: ${status.hasKey ? 'found' : 'missing'}.`,
    }
  }

  try {
    await saveRemoteRecord('diagnostics', 'last_test', {
      timestamp: new Date().toISOString(),
      userAgent: navigator.userAgent,
      origin: getAppBaseUrl(),
    })
    return { ok: true, message: 'Supabase write succeeded. Check app_records for diagnostics / last_test.' }
  } catch (error) {
    return {
      ok: false,
      message: error instanceof Error ? error.message : 'Supabase write failed.',
    }
  }
}

export async function hydrateLocalCollection<T>(
  storageKey: string,
  recordType: string,
  recordKey: string,
  options: {
    eventName?: string
    normalize?: (items: T[]) => T[]
    throwOnError?: boolean
  } = {},
) {
  if (!getClient()) {
    if (options.throwOnError) throw new Error('Atlas is not connected to Supabase. Please reload the app before trying again.')
    return readLocalCollection<T>(storageKey)
  }
  await collectionWrites.get(storageKey)?.catch(() => {})
  const version = collectionVersions.get(storageKey)
  try {
    const remote = await loadRemoteRecord<T[]>(recordType, recordKey, true)
    // A save started during this read. Its confirmed response owns the cache.
    if (version !== collectionVersions.get(storageKey)) {
      await collectionWrites.get(storageKey)?.catch(() => {})
      return readLocalCollection<T>(storageKey)
    }
    if (remote !== null && !Array.isArray(remote)) throw new Error('Supabase returned an invalid collection.')
    const items = options.normalize ? options.normalize(remote ?? []) : remote ?? []
    backupLocalCollection(storageKey, `before-hydrate-${recordType}`)
    writeLocalCollection(storageKey, items)
    if (options.eventName) window.dispatchEvent(new Event(options.eventName))
    return items
  } catch (error) {
    window.dispatchEvent(new CustomEvent('cronos:remote-sync-error', { detail: `Unable to load ${recordType} from Supabase. The displayed cache may be out of date. ${error instanceof Error ? error.message : ''}` }))
    if (options.throwOnError) throw error
    return readLocalCollection<T>(storageKey)
  }
}

type CollectionSyncOptions = {
  mergeById?: boolean
  changedIds?: string[]
  mergeItem?: (remoteItem: unknown, localItem: unknown) => unknown
  expectedItems?: unknown[]
  normalizeItem?: (item: any) => unknown
  rebaseProject?: (current: Project) => Project
}

export function saveLocalAndRemoteCollection<T>(
  storageKey: string,
  recordType: string,
  recordKey: string,
  items: T[],
  eventName?: string,
  options: CollectionSyncOptions = {},
) {
  backupLocalCollection(storageKey, `before-save-${recordType}`)
  const localSaved = writeLocalCollection(storageKey, items)
  if (eventName) window.dispatchEvent(new Event(eventName))
  if (!localSaved) {
    window.dispatchEvent(new CustomEvent('cronos:remote-sync-error', {
      detail: `This browser cache is full. Atlas is attempting to save the change to Supabase.`,
    }))
  }
  void saveRemoteCollection(recordType, recordKey, items, options).catch(error => {
    window.dispatchEvent(new CustomEvent('cronos:remote-sync-error', { detail: error instanceof Error ? error.message : 'Supabase sync failed.' }))
  })
}

export async function saveLocalAndRemoteCollectionStrict<T>(
  storageKey: string,
  recordType: string,
  recordKey: string,
  items: T[],
  eventName?: string,
  options: CollectionSyncOptions = {},
) {
  collectionVersions.set(storageKey, (collectionVersions.get(storageKey) ?? 0) + 1)
  const previous = collectionWrites.get(storageKey)
  const pending = (async () => {
  await previous?.catch(() => {})
  const savedItems = await saveRemoteCollection(recordType, recordKey, items, options)
  backupLocalCollection(storageKey, `before-save-${recordType}`)
  const localSaved = writeLocalCollection(storageKey, savedItems)
  if (eventName) window.dispatchEvent(new Event(eventName))
  if (!localSaved) {
    window.dispatchEvent(new CustomEvent('cronos:remote-sync-error', {
      detail: `Atlas saved this change to Supabase. This browser cache is full, so Atlas is using the confirmed Supabase copy in this tab; refresh the page to reload it from Supabase.`,
    }))
  }

  return savedItems
  })()
  collectionWrites.set(storageKey, pending)
  try { return await pending } finally {
    if (collectionWrites.get(storageKey) === pending) collectionWrites.delete(storageKey)
  }
}

async function saveRemoteCollection<T>(recordType: string, recordKey: string, items: T[], options: CollectionSyncOptions): Promise<T[]> {
  if (recordType === 'projects' || options.expectedItems) {
    const client = getClient()
    if (!client) throw new Error('Supabase is not configured. Nothing was saved.')
    const expected = (options.expectedItems ?? []) as T[]
    const changedIds = options.changedIds ?? [...new Set([...expected, ...items].map(recordId))]
    if (recordType === 'projects') {
      const changedFunds = (items as Project[]).filter(p => changedIds.includes(p.id) && isManagedFunds(p))
      if (changedFunds.length) {
        if (changedIds.length !== 1) throw new Error('Save Managed Funds projects individually through the authenticated API.')
        const snapshot = await readCollectionSnapshot(client, recordType, recordKey)
        const saved = await saveFundsProject(changedFunds[0])
        const current = snapshot?.data ?? []
        return (current.some(p => p.id === saved.project.id) ? current.map(p => p.id === saved.project.id ? saved.project : p) : [...current, saved.project]) as T[]
      }
    }
    return saveConfirmedCollection<T>(client, recordType, recordKey, remote => {
      if (recordType === 'projects' && (remote as Project[]).some(p => changedIds.includes(p.id) && isManagedFunds(p))) throw new Error('Managed Funds projects retain their history and require the authenticated API.')
      if (recordType === 'projects' && options.rebaseProject) {
        if (changedIds.length !== 1) throw new Error('Save quote changes one project at a time.')
        const current = (remote as Project[]).find(project => project.id === changedIds[0])
        if (!current) throw new Error('This opportunity was deleted. Nothing was saved.')
        const saved = options.rebaseProject(current)
        return remote.map(item => recordId(item) === current.id ? saved as T : item)
      }
      return mergeConfirmedChanges(remote, items, expected, changedIds, options.normalizeItem)
    })
  }
  if (!options.mergeById || !options.changedIds?.length) {
    return await saveRemoteRecord(recordType, recordKey, items)
  }

  const remote = await loadRemoteRecord<T[]>(recordType, recordKey, true)
  const merged = Array.isArray(remote) ? mergeCollectionByChangedIds(remote, items, options.changedIds, options.mergeItem) : items
  return await saveRemoteRecord(recordType, recordKey, merged)
}

function mergeCollectionByChangedIds<T>(
  remoteItems: T[],
  localItems: T[],
  changedIds: string[],
  mergeItem?: (remoteItem: unknown, localItem: unknown) => unknown,
) {
  const changed = new Set(changedIds)
  const localById = new Map(
    localItems
      .map(item => [recordId(item), item] as const)
      .filter((entry): entry is readonly [string, T] => Boolean(entry[0])),
  )
  const seen = new Set<string>()
  const merged = remoteItems.map(item => {
    const id = recordId(item)
    if (!id || !changed.has(id)) return item
    seen.add(id)
    const localItem = localById.get(id)
    return localItem && mergeItem ? (mergeItem(item, localItem) as T) : localItem ?? item
  })

  localItems.forEach(item => {
    const id = recordId(item)
    if (id && changed.has(id) && !seen.has(id)) {
      merged.push(item)
    }
  })

  return merged
}

function recordId(item: unknown) {
  if (!item || typeof item !== 'object' || !('id' in item)) return ''
  const id = (item as { id?: unknown }).id
  return typeof id === 'string' ? id : ''
}

export function readLocalCollection<T>(storageKey: string) {
  const volatile = volatileCollections.get(storageKey)
  if (volatile) return volatile as T[]

  try {
    const raw = collectionRaw(storageKey)
    return raw ? (JSON.parse(raw) as T[]) : []
  } catch {
    return []
  }
}

export function listLocalCollectionBackups(storageKey: string) {
  const prefix = `${storageKey}.backup.`
  return Object.keys(window.localStorage)
    .filter(key => key.startsWith(prefix) && key !== `${prefix}latest` && key !== `${prefix}latest.meta`)
    .sort()
    .reverse()
    .map(key => {
      const raw = window.localStorage.getItem(key) ?? '[]'
      return {
        key,
        createdAt: key.replace(prefix, '').replace(/-/g, ':').replace(/:(\d{3})Z$/, '.$1Z'),
        records: safeRecordCount(raw),
      }
    })
}

export async function restoreLocalCollectionBackup<T>(
  storageKey: string,
  backupKey: string,
  recordType: string,
  recordKey: string,
  eventName?: string,
) {
  const raw = window.localStorage.getItem(backupKey)
  if (!raw) throw new Error('Backup was not found in this browser.')

  const items = JSON.parse(raw) as T[]
  if (!Array.isArray(items)) throw new Error('Backup is not a valid collection.')

  backupLocalCollection(storageKey, `before-restore-${recordType}`)
  writeLocalCollection(storageKey, items)
  if (eventName) window.dispatchEvent(new Event(eventName))
  await saveRemoteRecord(recordType, recordKey, items)
  return items
}

function safeRecordCount(raw: string) {
  try {
    const value = JSON.parse(raw) as unknown
    return Array.isArray(value) ? value.length : 0
  } catch {
    return 0
  }
}

function backupLocalCollection(storageKey: string, reason: string) {
  if (storageKey === 'cronos.users') return
  const raw = window.localStorage.getItem(storageKey)
  if (!raw || raw === '[]') return
  if (raw.length > 1_500_000) {
    pruneBackups(storageKey, 0)
    return
  }

  const timestamp = new Date().toISOString().replace(/[:.]/g, '-')
  const backupKey = `${storageKey}.backup.${timestamp}`
  const latestKey = `${storageKey}.backup.latest`
  try {
    window.localStorage.setItem(backupKey, raw)
    window.localStorage.setItem(latestKey, raw)
    window.localStorage.setItem(`${latestKey}.meta`, JSON.stringify({ reason, createdAt: new Date().toISOString() }))
    pruneBackups(storageKey, 2)
  } catch (error) {
    console.warn(`Unable to back up ${storageKey} before ${reason}.`, error)
  }
}

function writeLocalCollection<T>(storageKey: string, items: T[]) {
  const serialized = JSON.stringify(items)
  if (storageKey === 'cronos.users') {
    authStorage.setItem(storageKey, serialized)
    volatileCollections.delete(storageKey)
    return true
  }
  try {
    window.localStorage.setItem(storageKey, serialized)
    volatileCollections.delete(storageKey)
    return true
  } catch (error) {
    if (!isQuotaExceededError(error)) throw error
  }

  pruneBackups(storageKey, 0)
  window.localStorage.removeItem(`${storageKey}.backup.latest`)
  window.localStorage.removeItem(`${storageKey}.backup.latest.meta`)

  try {
    window.localStorage.setItem(storageKey, serialized)
    volatileCollections.delete(storageKey)
    return true
  } catch (error) {
    if (!isQuotaExceededError(error)) throw error
    console.warn(`Unable to cache ${storageKey}; browser storage quota is full.`, error)
    volatileCollections.set(storageKey, items)
    return false
  }
}

function isQuotaExceededError(error: unknown) {
  return error instanceof DOMException && (
    error.name === 'QuotaExceededError' ||
    error.name === 'NS_ERROR_DOM_QUOTA_REACHED' ||
    error.code === 22 ||
    error.code === 1014
  )
}

function pruneBackups(storageKey: string, keep: number) {
  const prefix = `${storageKey}.backup.`
  const backupKeys = Object.keys(window.localStorage)
    .filter(key => key.startsWith(prefix) && key !== `${prefix}latest` && key !== `${prefix}latest.meta`)
    .sort()

  backupKeys.slice(0, Math.max(0, backupKeys.length - keep)).forEach(key => window.localStorage.removeItem(key))
}

