export function loadProjects(): Project[] {
  hydrateProjects()
  return readLocalCollection<Project>(STORAGE_KEY).map(normalizeProject)
}

function hydrateProjects() {
  if (hydrationStarted || typeof window === 'undefined') return
  hydrationStarted = true
  void refreshProjects()
}

export async function refreshProjects(options: { strict?: boolean } = {}) {
  hydrationStarted = true
  if (!projectsRefresh) {
    projectsRefresh = hydrateLocalCollection<Project>(STORAGE_KEY, REMOTE_TYPE, REMOTE_KEY, {
      eventName: 'cronos:projects-changed',
      normalize: projects => projects.map(normalizeProject),
      throwOnError: true,
    }).finally(() => { projectsRefresh = undefined })
  }
  try { return await projectsRefresh }
  catch (error) {
    if (options.strict) throw error
    return readLocalCollection<Project>(STORAGE_KEY).map(normalizeProject)
  }
}

export function saveProject(input: ProjectFormInput): Project {
  const project: Project = {
    ...input,
    id: crypto.randomUUID(),
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    checkbookStartingBalance: Number(input.checkbookStartingBalance || 0),
    materialBudget: Number(input.materialBudget || 0),
    quotes: [],
    quoteLines: [],
    purchaseOrders: [],
    inventory: [],
    kitStatus: 'Quoted',
    shipmentStatus: 'Quoted',
    materialShipments: [],
    materialTrackingActivity: [],
  }

  const linkedProject = linkProjectCustomer(project)
  saveProjects([linkedProject, ...loadProjects()], linkedProject.id)
  return linkedProject
}

export async function saveProjectStrict(input: ProjectFormInput): Promise<Project> {
  const project: Project = { ...input, id: crypto.randomUUID(), createdAt: new Date().toISOString(), updatedAt: new Date().toISOString(), quotes: [], quoteLines: [], purchaseOrders: [], inventory: [], kitStatus: 'Quoted', shipmentStatus: 'Quoted', materialShipments: [], materialTrackingActivity: [] }
  const linked = linkProjectCustomer(project)
  const saved = await saveProjectsStrict([linked, ...loadProjects()], linked.id)
  const confirmed = saved.find(item => item.id === linked.id)
  if (!confirmed) throw new Error('Supabase did not confirm the new project. Your form has been kept so you can try again.')
  return normalizeProject(confirmed)
}

export function loadProject(id: string): Project | undefined {
  return loadProjects().find(project => project.id === id)
}

export function saveMaterialTrackingProject(project: Project) {
  const normalized = normalizeProject(project)
  saveProjects(loadProjects().map(current => (current.id === normalized.id ? normalized : current)), normalized.id)
  return normalized
}

export function updateProjectFromInput(id: string, input: ProjectFormInput): Project | undefined {
  let updatedProject: Project | undefined
  const projects = loadProjects().map(project => {
    if (project.id !== id) return project
    if (isManagedFunds(project) && (input.projectType !== 'Managed Funds' || Number(input.checkbookStartingBalance) !== Number(project.checkbookStartingBalance))) throw new Error('Original funding and project type are locked. Create a Funding Modification Action.')

    const oldProjectNumber = project.projectNumber
    const projectNumber = input.projectNumber.trim()
    const projectName = input.projectName.trim()
    const customer = input.customer.trim()
    updatedProject = linkProjectCustomer(normalizeProject({
      ...project,
      ...input,
      projectNumber,
      projectName,
      customer,
      checkbookStartingBalance: Number(input.checkbookStartingBalance || 0),
      materialBudget: Number(input.materialBudget || 0),
      quotes: (project.quotes ?? []).map(quote => ({
        ...quote,
        projectNumber,
        projectName,
        customer,
        quoteNumber: replaceProjectPrefix(quote.quoteNumber, oldProjectNumber, projectNumber),
      })),
      purchaseOrders: project.purchaseOrders.map(po => ({
        ...po,
        poNumber: replaceProjectPrefix(po.poNumber, oldProjectNumber, projectNumber),
      })),
    }))
    return updatedProject
  })

  if (!updatedProject) return undefined

  saveProjects(projects, updatedProject.id)
  return updatedProject
}

export function deleteProject(projectId: string) {
  const projects = loadProjects()
  const projectToDelete = projects.find(project => project.id === projectId)

  if (!projectToDelete) {
    throw new Error('Project not found.')
  }
  if (isManagedFunds(projectToDelete)) throw new Error('Managed Funds projects retain their financial history and cannot be deleted.')

  saveProjects(projects.filter(project => project.id !== projectId))
  return projectToDelete
}

export function createQuoteForProject(
  projectId: string,
  lines: Array<Omit<QuoteLine, 'id' | 'approved'>>,
  options: { actionId?: string; contractFeeEnabled?: boolean; expirationDays?: 30 | 60 | 90; quoteName?: string; shippingCost?: number } = {},
): CustomerQuote {
  const { quote, projects } = prepareQuoteCreate(projectId, lines, options)
  saveProjects(projects, quote.projectId)
  return quote
}

export async function createQuoteForProjectStrict(
  projectId: string,
  lines: Array<Omit<QuoteLine, 'id' | 'approved'>>,
  options: { actionId?: string; contractFeeEnabled?: boolean; expirationDays?: 30 | 60 | 90; quoteName?: string; shippingCost?: number } = {},
): Promise<CustomerQuote> {
  const expected = loadProject(projectId)
  if (!expected) throw new Error('Project not found.')
  const { quote } = prepareQuoteCreate(projectId, lines, options)
  const saved = await saveQuoteChangeStrict(expected, undefined, current => {
    const createdQuote = { ...quote, quoteNumber: nextQuoteNumber(current) }
    const quotes = [createdQuote, ...current.quotes]
    return { ...current, quotes, quoteLines: quotes.flatMap(item => item.lines) }
  })
  return saved.quotes.find(item => item.id === quote.id)!
}

function prepareQuoteCreate(
  projectId: string,
  lines: Array<Omit<QuoteLine, 'id' | 'approved'>>,
  options: { actionId?: string; contractFeeEnabled?: boolean; expirationDays?: 30 | 60 | 90; quoteName?: string; shippingCost?: number } = {},
) {
  const project = loadProject(projectId)
  if (!project) {
    throw new Error('Project not found.')
  }

  const quoteLines: QuoteLine[] = lines.map(line => normalizeQuoteLineForSave({ ...line, id: crypto.randomUUID(), approved: false }))
  const quote: CustomerQuote = {
    id: crypto.randomUUID(),
    quoteNumber: nextQuoteNumber(project),
    projectId: project.id,
    projectNumber: project.projectNumber,
    projectName: project.projectName,
    customer: project.customer,
    quoteName: options.quoteName?.trim() ?? '',
    actionId: options.actionId,
    actionNumber: project.managedFunds?.actions.find(a => a.id === options.actionId)?.number,
    status: 'Quoted',
    createdAt: new Date().toISOString(),
    expirationDays: options.expirationDays ?? 30,
    contractFeeEnabled: options.contractFeeEnabled ?? false,
    shippingCost: normalizeMoney(options.shippingCost),
    lines: quoteLines,
  }

  const projects = loadProjects().map(current =>
    current.id === project.id
      ? normalizeProject({
          ...current,
          quotes: [quote, ...(current.quotes ?? [])],
          quoteLines: [...quoteLines, ...(current.quoteLines ?? [])],
        })
      : current,
  )

  return { quote, projects }
}

export function updateQuoteForProject(
  projectId: string,
  quoteId: string,
  lines: Array<Omit<QuoteLine, 'id' | 'approved'> & Partial<Pick<QuoteLine, 'id' | 'approved'>>>,
  options: { actionId?: string; contractFeeEnabled?: boolean; expirationDays?: 30 | 60 | 90; quoteName?: string; shippingCost?: number } = {},
): CustomerQuote {
  const { updatedQuote, updatedProject, projects, syncResult } = prepareQuoteUpdate(projectId, quoteId, lines, options)

  saveProjects(projects, updatedProject.id)
  finalizeQuoteUpdateSync(updatedProject, updatedQuote, syncResult)
  return updatedQuote
}

export async function updateQuoteForProjectStrict(
  projectId: string,
  quoteId: string,
  lines: Array<Omit<QuoteLine, 'id' | 'approved'> & Partial<Pick<QuoteLine, 'id' | 'approved'>>>,
  options: { expectedProject?: Project; actionId?: string; contractFeeEnabled?: boolean; expirationDays?: 30 | 60 | 90; quoteName?: string; shippingCost?: number } = {},
): Promise<CustomerQuote> {
  const expected = options.expectedProject ?? loadProject(projectId)
  if (!expected || expected.id !== projectId) throw new Error('Project not found.')
  let syncResult: QuotePoSyncResult
  const saved = await saveQuoteChangeStrict(expected, quoteId, current => {
    const prepared = prepareQuoteUpdate(projectId, quoteId, lines, options, current)
    syncResult = prepared.syncResult
    return prepared.updatedProject
  })
  const savedQuote = saved.quotes.find(item => item.id === quoteId)!
  finalizeQuoteUpdateSync(saved, savedQuote, syncResult!)
  return savedQuote
}

export async function deleteQuoteForProject(projectId: string, quoteId: string, expectedProject?: Project) {
  if (isManagedFunds(loadProject(projectId))) throw new Error('Managed Funds documents retain their history and cannot be deleted.')
  const project = expectedProject ?? loadProject(projectId)
  if (!project || project.id !== projectId) {
    throw new Error('Project not found.')
  }

  const quote = project.quotes?.find(item => item.id === quoteId)
  if (!quote) {
    throw new Error('Quote not found.')
  }

  const deletedPurchaseOrders = project.purchaseOrders.filter(po => po.quoteId === quoteId)
  const updatedProject = await saveQuoteChangeStrict(project, quoteId, current => {
    const quotes = current.quotes.filter(item => item.id !== quoteId)
    return {
      ...current,
      status: quotes.some(item => item.status === 'Customer Approved') ? 'Customer Approved' : 'Quoted',
      quotes,
      quoteLines: quotes.flatMap(item => item.lines),
      purchaseOrders: current.purchaseOrders.filter(po => po.quoteId !== quoteId),
    }
  })
  deleteCustomerOrdersForQuote(project.id, quote.id)

  return {
    project: updatedProject,
    quote,
    deletedPurchaseOrderCount: deletedPurchaseOrders.length,
  }
}

function prepareQuoteUpdate(
  projectId: string,
  quoteId: string,
  lines: Array<Omit<QuoteLine, 'id' | 'approved'> & Partial<Pick<QuoteLine, 'id' | 'approved'>>>,
  options: { actionId?: string; contractFeeEnabled?: boolean; expirationDays?: 30 | 60 | 90; quoteName?: string; shippingCost?: number } = {},
  sourceProject?: Project,
) {
  const project = sourceProject ?? loadProject(projectId)
  if (!project) {
    throw new Error('Project not found.')
  }

  const existingQuote = project.quotes?.find(quote => quote.id === quoteId)
  if (!existingQuote) {
    throw new Error('Quote not found.')
  }

  const quoteLines: QuoteLine[] = lines.map(line => ({
    ...normalizeQuoteLineForSave(line),
    approved: existingQuote.status === 'Customer Approved' ? true : line.approved ?? false,
  }))
  const updatedQuote: CustomerQuote = {
    ...existingQuote,
    quoteName: options.quoteName?.trim() ?? existingQuote.quoteName ?? '',
    expirationDays: options.expirationDays ?? existingQuote.expirationDays ?? 30,
    contractFeeEnabled: options.contractFeeEnabled ?? existingQuote.contractFeeEnabled ?? false,
    shippingCost: normalizeMoney(options.shippingCost ?? existingQuote.shippingCost),
    lines: quoteLines,
  }
  const quotes = (project.quotes ?? []).map(quote => (quote.id === quoteId ? updatedQuote : quote))
  const projectWithQuote = normalizeProject({
    ...project,
    quotes,
    quoteLines: quotes.flatMap(quote => quote.lines),
  })
  const syncResult = syncPurchaseOrdersForQuote(projectWithQuote, updatedQuote)
  const updatedProject = syncResult.project
  const projects = loadProjects().map(current => (current.id === project.id ? updatedProject : current))

  return { updatedQuote, updatedProject, projects, syncResult }
}

function finalizeQuoteUpdateSync(updatedProject: Project, updatedQuote: CustomerQuote, syncResult: ReturnType<typeof syncPurchaseOrdersForQuote>) {
  if (syncResult.touchedPurchaseOrders.length) {
    recordPurchaseOrdersInCatalog(updatedProject, syncResult.touchedPurchaseOrders)
    syncCustomerOrdersFromApprovedProjects([updatedProject])
  }
  logQuotePoSync(updatedQuote, syncResult)
}

export function updateQuoteName(projectId: string, quoteId: string, quoteName: string) {
