create or replace function public.atlas_commit_managed_funds(p_project_id text,p_expected_revision bigint,p_previous_project jsonb,p_project jsonb,p_state jsonb)
returns jsonb language plpgsql security definer set search_path=public as $$
declare current_projects jsonb; current_project jsonb; old_state jsonb; old_revision bigint; new_revision bigint; item jsonb; allocation jsonb; historical jsonb; next_projects jsonb;
begin
  -- Serialize every project write through the shared collection row, then lock the ledger.
  insert into app_records(record_type,record_key,data) values('projects','all','[]') on conflict(record_type,record_key) do nothing;
  select data into current_projects from app_records where record_type='projects' and record_key='all' for update;
  select p into current_project from jsonb_array_elements(current_projects) p where p->>'id'=p_project_id;
  if (current_project - 'managedFunds') is distinct from (p_previous_project - 'managedFunds') then raise exception 'Project conflict'; end if;
  select state,revision into old_state,old_revision from atlas_managed_funds where project_id=p_project_id for update;
  if coalesce(old_revision,-1) <> p_expected_revision then raise exception 'Revision conflict'; end if;
  if p_state->>'projectId' <> p_project_id or p_project->>'id' <> p_project_id or p_project->>'projectType'<>'Managed Funds' then raise exception 'Invalid project identity'; end if;
  if old_state is not null then
    if p_state->'originalFunding' is distinct from old_state->'originalFunding' then raise exception 'Original funding is immutable'; end if;
    foreach historical in array array['"transactions"'::jsonb,'"audit"'::jsonb,'"commands"'::jsonb] loop
      for item in select value from jsonb_array_elements(old_state->(historical #>> '{}')) loop
        if not (p_state->(historical #>> '{}') @> jsonb_build_array(item)) then raise exception 'Financial history is append-only'; end if;
      end loop;
    end loop;
    for item in select value from jsonb_array_elements(old_state->'actions') loop
      if not exists(select 1 from jsonb_array_elements(p_state->'actions') a where a->>'id'=item->>'id' and a->>'number'=item->>'number') then raise exception 'Actions cannot be removed or renumbered'; end if;
    end loop;
    for item in select value from jsonb_array_elements(old_state->'invoices') loop
      if not exists(select 1 from jsonb_array_elements(p_state->'invoices') i where i->>'id'=item->>'id' and i->'allocations'=item->'allocations' and i->>'number'=item->>'number' and i->'total'=item->'total' and (item->>'status'='Draft' or i=item)) then raise exception 'Invoice history cannot be rewritten'; end if;
    end loop;
    for item in select value from jsonb_array_elements(old_state->'documents') loop
      if not (p_state->'documents' @> jsonb_build_array(item)) then raise exception 'Documents cannot be removed'; end if;
    end loop;
  else
    insert into atlas_managed_funds_legacy_backups(project_id,source) values(p_project_id,coalesce(current_project,p_project)) on conflict do nothing;
  end if;
  new_revision := coalesce(old_revision,0)+1;
  p_state := jsonb_set(p_state,'{revision}',to_jsonb(new_revision));
  insert into atlas_managed_funds(project_id,revision,state) values(p_project_id,new_revision,p_state)
  on conflict(project_id) do update set revision=excluded.revision,state=excluded.state,updated_at=now();
  for item in select value from jsonb_array_elements(p_state->'actions') loop
    insert into atlas_managed_funds_actions(id,project_id,action_number,data) values(item->>'id',p_project_id,item->>'number',item)
    on conflict(id) do update set data=excluded.data where atlas_managed_funds_actions.project_id=excluded.project_id;
  end loop;
  for item in select value from jsonb_array_elements(p_state->'transactions') loop
    insert into atlas_managed_funds_transactions(id,project_id,action_id,data) values(item->>'id',p_project_id,item->>'actionId',item) on conflict do nothing;
  end loop;
  for item in select value from jsonb_array_elements(p_state->'audit') loop
    insert into atlas_managed_funds_audit(id,project_id,data) values(item->>'id',p_project_id,item) on conflict do nothing;
  end loop;
  for item in select value from jsonb_array_elements(p_state->'invoices') loop
    insert into atlas_managed_funds_invoices(id,project_id,invoice_number,data) values(item->>'id',p_project_id,item->>'number',item)
    on conflict(id) do update set data=excluded.data where atlas_managed_funds_invoices.project_id=excluded.project_id;
    for allocation in select value from jsonb_array_elements(item->'allocations') loop
      insert into atlas_managed_funds_invoice_allocations(id,project_id,invoice_id,action_id,amount_cents,data) values(allocation->>'id',p_project_id,item->>'id',allocation->>'actionId',(allocation->>'amount')::bigint,allocation) on conflict do nothing;
    end loop;
  end loop;
  for item in select value from jsonb_array_elements(p_state->'documents') loop
    insert into atlas_managed_funds_documents(id,project_id,action_id,data) values(item->>'id',p_project_id,item->>'actionId',item) on conflict do nothing;
  end loop;
  for item in select value from jsonb_array_elements(coalesce(p_project->'quotes','[]')) loop
    insert into atlas_managed_funds_document_links(project_id,action_id,document_kind,source_id) values(p_project_id,item->>'actionId','Customer Quote',item->>'id') on conflict do nothing;
  end loop;
  for item in select value from jsonb_array_elements(coalesce(p_project->'purchaseOrders','[]')) loop
    insert into atlas_managed_funds_document_links(project_id,action_id,document_kind,source_id) values(p_project_id,item->>'actionId','Purchase Order',item->>'id') on conflict do nothing;
  end loop;
  p_project := jsonb_set(p_project - 'managedFunds','{managedFundsRevision}',to_jsonb(new_revision));
  select coalesce(jsonb_agg(case when p->>'id'=p_project_id then p_project else p end order by n),'[]') into next_projects from jsonb_array_elements(current_projects) with ordinality a(p,n);
  if current_project is null then next_projects := next_projects || jsonb_build_array(p_project); end if;
  update app_records set data=next_projects,updated_at=now() where record_type='projects' and record_key='all';
  return jsonb_build_object('revision',new_revision);
end $$;
revoke all on function public.atlas_commit_managed_funds(text,bigint,jsonb,jsonb,jsonb) from public,anon,authenticated;
grant execute on function public.atlas_commit_managed_funds(text,bigint,jsonb,jsonb,jsonb) to service_role;

-- Standard projects keep the existing permissions and workflows. This merge cannot
-- alter/delete any Managed Funds object, including when an old client submits a stale collection.
create or replace function public.atlas_merge_standard_projects(p_projects jsonb) returns jsonb
language plpgsql security definer set search_path=public as $$
declare existing jsonb; merged jsonb;
begin
  if jsonb_typeof(p_projects)<>'array' then raise exception 'Projects must be an array'; end if;
  select data into existing from app_records where record_type='projects' and record_key='all' for update;
  if exists(select 1 from jsonb_array_elements(p_projects) p where p->>'projectType' in ('Managed Funds','Checkbook')) then raise exception 'Managed Funds requires the authenticated API'; end if;
  select coalesce(jsonb_agg(p),'[]') into merged from jsonb_array_elements(p_projects) p where not exists(select 1 from jsonb_array_elements(coalesce(existing,'[]')) e where e->>'id'=p->>'id' and e->>'projectType' in ('Managed Funds','Checkbook'));
  merged := merged || (select coalesce(jsonb_agg(p),'[]') from jsonb_array_elements(coalesce(existing,'[]')) p where p->>'projectType' in ('Managed Funds','Checkbook'));
  insert into app_records(record_type,record_key,data) values('projects','all',merged) on conflict(record_type,record_key) do update set data=excluded.data,updated_at=now();
  return merged;
end $$;
revoke all on function public.atlas_merge_standard_projects(jsonb) from public;
grant execute on function public.atlas_merge_standard_projects(jsonb) to anon,authenticated,service_role;

create or replace function public.atlas_guard_managed_project() returns trigger language plpgsql set search_path=public as $$
declare item jsonb; candidate jsonb;
begin
  if current_user in ('postgres','supabase_admin','service_role') then if tg_op='DELETE' then return old; else return new; end if; end if;
  if coalesce(new.record_type,old.record_type)<>'projects' then if tg_op='DELETE' then return old; else return new; end if; end if;
  if tg_op<>'INSERT' then
    for item in select value from jsonb_array_elements(old.data) where value->>'projectType' in ('Managed Funds','Checkbook') loop
      if tg_op='DELETE' then raise exception 'Managed Funds history cannot be deleted'; end if;
      select p into candidate from jsonb_array_elements(new.data) p where p->>'id'=item->>'id';
      if candidate is distinct from item then raise exception 'Managed Funds changes require the authenticated API'; end if;
    end loop;
  end if;
  if tg_op<>'DELETE' then
    for item in select value from jsonb_array_elements(new.data) where value->>'projectType' in ('Managed Funds','Checkbook') loop
      if tg_op='INSERT' or not exists(select 1 from jsonb_array_elements(old.data) p where p=item) then raise exception 'Managed Funds creation requires the authenticated API'; end if;
    end loop;
    return new;
  end if;
  return old;
end $$;
drop trigger if exists atlas_guard_managed_project on public.app_records;
create trigger atlas_guard_managed_project before insert or update or delete on public.app_records for each row execute function public.atlas_guard_managed_project();
insert into storage.buckets(id,name,public,file_size_limit) values('atlas-managed-funds','atlas-managed-funds',false,20971520) on conflict(id) do nothing;
commit;

-- Data-preserving rollback for projects that have not entered the new financial workflow.
-- Stop application writes before running. Never drop ledgers, documents, or backups.
begin;
update public.app_records r set data=(
  select coalesce(jsonb_agg(case when b.project_id is not null and not exists(select 1 from public.atlas_managed_funds f where f.project_id=p->>'id') then jsonb_set(p,'{projectType}',b.source->'projectType') else p end order by n),'[]')
  from jsonb_array_elements(r.data) with ordinality a(p,n)
  left join public.atlas_managed_funds_legacy_backups b on b.project_id=p->>'id'
) where r.record_type='projects' and r.record_key='all';
-- Enrolled projects retain Managed Funds labels and all history. Do not reopen them
-- in a pre-migration client; export/reconcile first if a full product rollback is needed.
commit;

import test from 'node:test'
import assert from 'node:assert/strict'
import { randomUUID } from 'node:crypto'
import { applyManagedFundsCommand as apply, initializeManagedFunds, financialSummary, actionFinancials, billingStatus, reconcileManagedProject, procurementStatus, cents, canManageFunds } from '../../src/domain/managedFunds.mjs'
import { generateVendorPurchaseOrders, calculateQuoteSummary } from '../../src/services/calculations.ts'
import { createMaterialShipment, markMaterialShipmentDelivered } from '../../src/services/materialTracking.ts'
import { handleManagedFundsApi } from '../managed-funds-api.mjs'

const admin = { id:'admin1',name:'Finance Admin',role:'admin' }, buyer = { id:'buyer1',name:'Procurement',role:'procurement' }
const base = (type='Managed Funds') => ({ id:'project1',projectType:type,projectNumber:'26-087',projectName:'CCoE FY27 Managed Funds',customer:'CCoE',customerAddress1:'123 Customer St',customerCity:'Augusta',customerState:'GA',customerZip:'30901',checkbookStartingBalance:1_000_000,quotes:[],quoteLines:[],purchaseOrders:[],materialShipments:[],materialTrackingActivity:[],inventory:[],notes:'Original project notes',legacyDocuments:[{id:'doc1',name:'Original authorization.pdf'}] })
const command = (type,input={},actionId) => ({id:randomUUID(),type,input,...(actionId?{actionId}:{})})
const run = (state,type,input={},actionId,actor=admin,options={}) => apply(state,command(type,input,actionId),actor,options)
function create(state,type='Purchase Material',description='Network equipment',bill=100_000,cost=80_000) {
  const next=run(state,'create',{type,description,authorizedAmount:cents(bill),estimatedCost:cents(cost),billAmount:cents(bill),requestDate:'2026-09-14',requestor:'Customer',vendors:['Vendor A','Vendor B']},undefined,buyer)
  return [next,next.actions.at(-1).id]
}
function approved(state,id,amount) { return run(state,'approve',{commitment:cents(amount),reason:'Customer authorization verified'},id) }

test('complete Managed Funds material, expense, consolidated billing, credits and modification workflow',()=>{
  let {state,project}=initializeManagedFunds(base(),admin)
  assert.equal(financialSummary(state).authorized,cents(1_000_000))
  let id; [state,id]=create(state); state=approved(state,id,100_000)
  const lines=['Vendor A','Vendor B'].map((vendor,index)=>({id:`l${index}`,clin:String(index+1),partNumber:`PART-${index}`,manufacturer:'Cisco',description:'Network equipment',quantity:1,unitCost:index?40_000:30_000,markupPercent:25,vendor,quoteNumber:`VQ-${index}`,leadTime:'2 weeks',approved:true}))
  const quote={id:'q1',actionId:id,quoteNumber:'Q-26-184',projectId:project.id,projectNumber:project.projectNumber,projectName:project.projectName,customer:project.customer,status:'Customer Approved',createdAt:'2026-09-14',lines}
  ;({state,project}=reconcileManagedProject(state,project,{...project,quotes:[quote]},admin))
  const pos=generateVendorPurchaseOrders(lines,project.projectNumber).map(p=>({...p,quoteId:quote.id,actionId:id}))
  assert.equal(pos.length,2)
  ;({state,project}=reconcileManagedProject(state,project,{...project,purchaseOrders:pos},buyer))
  assert.equal(state.actions.find(a=>a.id===id).poIds.length,2)
  let tracked=project
  for(const po of project.purchaseOrders) {
    tracked=createMaterialShipment(tracked,{poId:po.id,carrier:'UPS',trackingNumber:`1Z-${po.id}`,actualShipDate:'2026-09-14',lines:po.lines.map(l=>({poId:po.id,melLineItemId:l.id,quantity:l.quantityOrdered}))},{...buyer,role:'Procurement Team'})
    tracked=markMaterialShipmentDelivered(tracked,tracked.materialShipments.at(-1).id,'2026-09-15',{...buyer,role:'Procurement Team'})
  }
  ;({state,project}=reconcileManagedProject(state,project,tracked,buyer))
  assert.equal(procurementStatus(project,state.actions[0]),'Delivered')
  state=run(state,'expense',{vendor:'Vendor A',vendorInvoiceNumber:'VA-001',description:'Equipment cost',expenseDate:'2026-09-14',actualCost:cents(30_000),billAmount:0},id,buyer)
  state=run(state,'expense',{vendor:'Vendor B',vendorInvoiceNumber:'VB-001',description:'Equipment cost',expenseDate:'2026-09-14',actualCost:cents(40_000),billAmount:0},id,buyer)
  state=run(state,'ready',{ready:true},id,buyer)
  state=run(state,'draft_invoice',{projectNumber:project.projectNumber,allocations:[{actionId:id,amount:cents(100_000)}]},undefined,buyer,{project})
  const materialInvoice=state.invoices.at(-1).id
  assert.equal(state.invoices.at(-1).customerSnapshot.customer,'CCoE')
  state=run(state,'issue_invoice',{invoiceId:materialInvoice},undefined,buyer)
  assert.equal(billingStatus(state,state.actions[0]),'Invoiced')
  let truck; [state,truck]=create(state,'Direct Expense / Pass-Through','Truck rental',1200,1000); state=approved(state,truck,1200)
  state=run(state,'document',{name:'Truck rental.pdf',storagePath:`${project.id}/${truck}/receipt.pdf`,size:1000,kind:'Vendor invoice / receipt'},truck,buyer)
  state=run(state,'expense',{vendor:'Truck Rental',vendorInvoiceNumber:'TR-001',description:'Truck rental',expenseDate:'2026-09-14',actualCost:cents(1000),billAmount:cents(1200),documentId:state.documents.at(-1).id},truck,buyer)
  assert.equal(state.actions.find(a=>a.id===truck).quoteIds.length,0)
  state=run(state,'ready',{ready:true},truck,buyer)
  let billing; [state,billing]=create(state,'Create Customer Invoice','Standalone billing',5000,0); state=approved(state,billing,5000); state=run(state,'ready',{ready:true},billing,buyer)
  state=run(state,'draft_invoice',{allocations:[{actionId:truck,amount:cents(1200)},{actionId:billing,amount:cents(5000)}]},undefined,buyer)
  const consolidated=state.invoices.at(-1); assert.equal(consolidated.allocations.length,2)
  state=run(state,'issue_invoice',{invoiceId:consolidated.id},undefined,buyer)
  const adjustment=description=>{state=run(state,'create',{type:'Credit / Adjustment',description});return state.actions.at(-1).id}
  const customerCredit=adjustment('Customer pricing credit')
  state=run(state,'adjust',{kind:'Customer Credit',targetActionId:truck,invoiceId:consolidated.id,amount:cents(-200),reason:'Rental pricing correction',reference:'CC-001'},customerCredit)
  const vendorCredit=adjustment('Vendor rental credit')
  state=run(state,'adjust',{kind:'Vendor Credit',targetActionId:truck,amount:cents(-100),reason:'Vendor refund',reference:'VC-001'},vendorCredit)
  for(const [n,value] of [[1,500_000],[2,-100_000]]) {
    state=run(state,'create',{type:'Funding Modification',description:`Modification ${n}`})
    state=run(state,'funding',{amount:cents(value),reference:`MOD-${n}`,reason:'Signed customer modification'},state.actions.at(-1).id)
  }
  assert.deepEqual(financialSummary(state),{authorized:cents(1_400_000),committed:cents(106_200),actualCost:cents(70_900),billAmount:cents(106_000),invoiced:cents(106_000),paid:0,available:cents(1_293_800),unbilled:cents(1_294_000)})
  assert.equal(actionFinancials(state,truck).billable,0,'credit does not silently make refunded amount billable again')
  const priorTransactions=structuredClone(state.transactions)
  state=run(state,'payment',{invoiceId:consolidated.id,amount:cents(6000),reference:'ACH-001'},undefined,buyer)
  assert.equal(financialSummary(state).paid,cents(6000))
  assert.deepEqual(state.transactions.slice(0,priorTransactions.length),priorTransactions)
  assert.ok(state.audit.every(a=>a.userId&&a.occurredAt&&'previous'in a&&'next'in a))
})

test('over-commitment and funding decreases are controlled, including mandatory override explanations',()=>{
  let {state}=initializeManagedFunds(base(),admin);let id;[state,id]=create(state,'Purchase Material','Over budget',1_100_000)
  assert.throws(()=>approved(state,id,1_100_000),e=>e.message==='Insufficient Available Funding'&&e.details.projectedRemainingBalance===cents(-100_000))
  assert.throws(()=>run(state,'approve',{commitment:cents(1_100_000),reason:'Requested',overrideReason:'Management authorized'},id,buyer),/Permission/)
  state=run(state,'approve',{commitment:cents(1_100_000),reason:'Approved',overrideReason:'Management funding exception 27'},id)
  assert.ok(state.audit.some(a=>a.operation==='Funding limit override'&&a.reason==='Management funding exception 27'))
  state=run(state,'create',{type:'Funding Modification',description:'Decrease'})
  assert.throws(()=>run(state,'funding',{amount:cents(-100),reference:'MOD',reason:'Decrease'},state.actions.at(-1).id),/Insufficient/)
})
test('permissions distinguish ordinary work from financial approval, funding, credits and overrides',()=>{
  for(const role of ['engineering','sales','procurement']) for(const p of ['approve','funding','adjust','override']) assert.equal(canManageFunds({id:'u',role},p),false)
  assert.equal(canManageFunds(buyer,'expense'),true);assert.equal(canManageFunds({id:'sales',role:'sales'},'invoice'),true);assert.equal(canManageFunds({id:'sales',role:'sales'},'issue_po'),false)
  assert.equal(canManageFunds({...buyer,permissions:['atlas.managed_funds.approve']},'approve'),true)
})
test('draft reservations, re-issue, payment replay and cross-project allocation guards prevent duplicate billing',()=>{
  let {state}=initializeManagedFunds(base(),admin);let id;[state,id]=create(state);state=approved(state,id,100_000);state=run(state,'ready',{ready:true},id)
  assert.throws(()=>run(state,'draft_invoice',{allocations:[{actionId:'another-project-action',amount:100}]}),/Ready to Bill/)
  assert.throws(()=>run(state,'draft_invoice',{allocations:[{actionId:id,amount:100},{actionId:id,amount:100}]}),/once/)
  state=run(state,'draft_invoice',{allocations:[{actionId:id,amount:cents(100_000)}]})
  assert.throws(()=>run(state,'draft_invoice',{allocations:[{actionId:id,amount:1}]}),/Duplicate or excess/)
  assert.throws(()=>run(state,'edit',{billAmount:0,reason:'Reduce'},id),/issued and reserved/)
  const invoice=state.invoices[0]
  state=run(state,'issue_invoice',{invoiceId:invoice.id});assert.throws(()=>run(state,'issue_invoice',{invoiceId:invoice.id}),/already/)
  state=run(state,'payment',{invoiceId:invoice.id,amount:cents(100_000),reference:'PAY-1'});assert.throws(()=>run(state,'payment',{invoiceId:invoice.id,amount:1,reference:'PAY-1'}),/already/)
  assert.equal(billingStatus(state,state.actions[0]),'Paid')
})
test('idempotent command retry returns unchanged state and conflicting reuse fails',()=>{
  const {state}=initializeManagedFunds(base(),admin),cmd=command('create',{type:'Purchase Material',description:'Single action'})
  const once=apply(state,cmd,buyer),twice=apply(once,cmd,buyer)
  assert.deepEqual(twice,once);assert.throws(()=>apply(once,{...cmd,input:{...cmd.input,description:'Different'}},buyer),/already used/)
  assert.throws(()=>apply(once,cmd,admin),/already used/)
})
