  original.quotes=[{id:'quote1',quoteNumber:'Q1',quoteName:'Legacy quote',status:'Customer Approved',createdAt:'2020-01-01',lines:[{id:'line1',quantity:1,unitCost:100,markupPercent:20}]}]
