  assert.equal(local.getItem('sb-test-auth-token'), 'token')
  assert.equal(adapter(local, session).getItem('sb-test-auth-token'), 'token')
  session.setItem('sb-test-auth-token', 'old fallback')
  storage.removeItem('sb-test-auth-token')
