function readJson<T>(key: string, fallback: T): T {
  try {
    const raw = window.localStorage.getItem(key)
    return raw ? (JSON.parse(raw) as T) : fallback
  } catch {
    return fallback
  }
}

function offsetDate(days: number) {
  const date = new Date()
  date.setDate(date.getDate() + days)
  return date.toISOString()
}

function daysUntil(value: string) {
  if (!value) return 999
  const now = new Date()
  const date = new Date(value)
  return Math.ceil((date.getTime() - now.getTime()) / 86400000)
}

function daysSince(value: string) {
  if (!value) return 999
  return Math.max(0, -daysUntil(value))
}

export const conflictMessage = 'This project or record changed in Supabase while you were editing. Your change was not saved. Reload Atlas, review the latest version, and try again.'

// JSON object key order can differ between PostgreSQL JSONB and the browser.
export function sameRecord(a, b) {
  const canonical = value => Array.isArray(value) ? value.map(canonical)
    : value && typeof value === 'object' ? Object.fromEntries(Object.keys(value).sort().filter(key => value[key] !== undefined).map(key => [key, canonical(value[key])])) : value
  return JSON.stringify(canonical(a)) === JSON.stringify(canonical(b))
}

export function mergeConfirmedChanges(remote, incoming, expected, changedIds, normalize = value => value) {
  const changed = new Set(changedIds)
  const byId = items => new Map(items.map(item => [item.id, item]))
  const remoteById = byId(remote), expectedById = byId(expected), incomingById = byId(incoming)
  for (const id of changed) {
    const current = remoteById.get(id), before = expectedById.get(id)
    if (!sameRecord(current === undefined ? current : normalize(current), before === undefined ? before : normalize(before))) throw new Error(conflictMessage)
  }
  const result = remote.filter(item => !changed.has(item.id) || incomingById.has(item.id))
    .map(item => changed.has(item.id) ? incomingById.get(item.id) : item)
  for (const item of incoming) if (changed.has(item.id) && !remoteById.has(item.id)) result.push(item)
  return result
}

export async function readCollectionSnapshot(client, recordType, recordKey) {
  const { data, error } = await client.from('app_records').select('data,updated_at')
    .eq('record_type', recordType).eq('record_key', recordKey).maybeSingle()
  if (error) throw new Error(error.message)
  if (data && (!Array.isArray(data.data) || !data.updated_at)) throw new Error('Supabase returned an invalid collection. Nothing was saved.')
  return data
}

// The timestamp predicate is checked atomically by PostgreSQL. A competing
// writer forces a fresh read and revalidation, never an unconditional overwrite.
export async function saveConfirmedCollection(client, recordType, recordKey, transform) {
  for (let attempt = 0; attempt < 3; attempt++) {
    const snapshot = await readCollectionSnapshot(client, recordType, recordKey)
    const next = transform(snapshot?.data ?? [])
    if (snapshot && sameRecord(next, snapshot.data)) return snapshot.data
    const row = { data: next, updated_at: new Date().toISOString() }
    const result = snapshot
      ? await client.from('app_records').update(row).eq('record_type', recordType).eq('record_key', recordKey)
        .eq('updated_at', snapshot.updated_at).select('data').maybeSingle()
      : await client.from('app_records').insert({ ...row, record_type: recordType, record_key: recordKey }).select('data').maybeSingle()
    if (result.error) {
      if (!snapshot && result.error.code === '23505') continue
      throw new Error(result.error.message)
    }
    if (result.data) return result.data.data
  }
  throw new Error(conflictMessage)
}

import test from 'node:test'
import assert from 'node:assert/strict'
import { mergeConfirmedChanges, sameRecord, saveConfirmedCollection } from '../../src/services/confirmedCollection.mjs'
const before = [{id:'p',quotes:[{id:'q',lines:[{id:'a'},{id:'b'}]}],purchaseOrders:[{id:'po',quoteId:'q'}]}]
test('quote removal replaces nested arrays while retaining unrelated remote projects', () => {
 const other={id:'other',quotes:[{id:'remote-only'}]}
 const after=[{id:'p',quotes:[],purchaseOrders:[]}]
 assert.deepEqual(mergeConfirmedChanges([...before,other],after,before,['p']),[...after,other])
})
test('edited quote lines replace the prior lines instead of restoring removed lines', () => {
 const after=[{...before[0],quotes:[{id:'q',lines:[{id:'a',description:'edited'}]}]}]
 assert.deepEqual(mergeConfirmedChanges(before,after,before,['p']),after)
})
test('stale edits and attempts to recreate remotely deleted projects are rejected', () => {
 assert.throws(()=>mergeConfirmedChanges([{...before[0],notes:'new edit'}],before,before,['p']),/changed in Supabase/)
 assert.throws(()=>mergeConfirmedChanges([],before,before,['p']),/changed in Supabase/)
})
test('JSONB key order and omitted undefined fields do not produce false conflicts', () => {
 assert.equal(sameRecord({b:2,a:1,empty:undefined},{a:1,b:2}),true)
 assert.equal(sameRecord([{id:'a'},{id:'b'}],[{id:'b'},{id:'a'}]),false)
})
test('failed remote reads never attempt a write', async () => {
 const client={from:()=>({select(){return this},eq(){return this},maybeSingle:async()=>({error:{message:'Read failed'}})})}
 await assert.rejects(saveConfirmedCollection(client,'projects','all',()=>{throw new Error('Must not transform after failed read')}),/Read failed/)
})
test('absent records can only be initialized by a confirmed insert', async () => {
 let inserted
 const query={select(){return this},eq(){return this},insert(row){inserted=row;return this},maybeSingle:async()=>inserted?{data:{data:inserted.data}}:{data:null}}
 const result=await saveConfirmedCollection({from:()=>query},'projects','all',()=>before)
 assert.deepEqual(result,before);assert.equal(inserted.record_type,'projects');assert.equal(inserted.record_key,'all')
})

import { sameRecord } from './confirmedCollection.mjs'

// Compare the document the user actually opened. A refreshed cache is not a
// replacement for that baseline. Other quotes and project notes may change.
export function assertQuoteUnchanged(current, expected, quoteId, checkPurchaseOrders = true) {
  for (const key of ['id', 'projectType', 'projectNumber', 'projectName', 'customer', 'customerId']) {
    if (!sameRecord(current[key], expected[key])) {
      throw new Error('This opportunity\'s details changed in Supabase while you were editing. Your change was not saved. Review the latest opportunity before trying again.')
    }
  }
  if (!quoteId) return
  const quote = current.quotes.find(item => item.id === quoteId)
  const original = expected.quotes.find(item => item.id === quoteId)
  if (!quote || !original || !sameRecord(quote, original)) {
    throw new Error('This quote changed in Supabase while you were editing. Your change was not saved. Your draft is still on this screen; review the latest quote in another tab before trying again.')
  }
  if (checkPurchaseOrders && !sameRecord(
    current.purchaseOrders.filter(po => po.quoteId === quoteId),
    expected.purchaseOrders.filter(po => po.quoteId === quoteId),
  )) {
    throw new Error('A purchase order linked to this quote changed in Supabase while you were editing. Your change was not saved. Review the latest purchase order before trying again.')
  }
}

import test from 'node:test'
import assert from 'node:assert/strict'
import { assertQuoteUnchanged } from '../../src/services/quoteConcurrency.mjs'
const project = () => ({ id: 'p', projectType: 'Resale', projectNumber: 'TEST', projectName: 'Test', customer: 'Customer', quotes: [{ id: 'q1', status: 'Quoted', lines: [{ id: 'l1', quantity: 2, approved: false }] }, { id: 'q2', status: 'Quoted', lines: [] }], purchaseOrders: [{ id: 'po1', quoteId: 'q1', status: 'Ordered' }, { id: 'po2', quoteId: 'q2', status: 'Ordered' }] })
test('quote checks allow unrelated approvals, notes, purchase orders and update timestamps', () => {
 const expected=project(), current=project()
 current.quotes[1].status='Customer Approved';current.notes='Another user';current.updatedAt='new';current.purchaseOrders[1].status='Delivered'
 assert.doesNotThrow(()=>assertQuoteUnchanged(current,expected,'q1'))
})
test('quote checks reject changed prices/quantities, changed approval and remotely deleted quotes', () => {
 const expected=project()
 for(const change of [p=>p.quotes[0].lines[0].quantity=3,p=>p.quotes[0].status='Customer Approved',p=>p.quotes.shift()]) {
  const current=project();change(current);assert.throws(()=>assertQuoteUnchanged(current,expected,'q1'),/This quote changed in Supabase/)
 }
})
test('linked purchase order changes block replacement or deletion but allow approval', () => {
 const expected=project(), current=project();current.purchaseOrders[0].status='Delivered'
 assert.throws(()=>assertQuoteUnchanged(current,expected,'q1'),/purchase order linked/)
 assert.doesNotThrow(()=>assertQuoteUnchanged(current,expected,'q1',false))
})
test('new quotes can be added alongside other quote changes but project identity and pricing type stay guarded', () => {
 const expected=project(), current=project();current.quotes.push({id:'q3'});assert.doesNotThrow(()=>assertQuoteUnchanged(current,expected))
 for(const key of ['id','projectType','projectNumber','projectName','customer','customerId']) {
  assert.throws(()=>assertQuoteUnchanged({...current,[key]:'changed'},expected),/opportunity's details changed/)
 }
})
